 const stockTabs=()=>'<div class="op-filter">'+[['stock','Stock'],['transfers','Transfers']].map(([id,label])=>'<button data-op="stock-view" data-value="'+id+'" class="'+(stockView===id?'active':'')+'">'+label+'</button>').join('')+'</div>';
