 const skillIcon=b=>{const s=[b.goalSkill,b.rateSkill,b.role].map(x=>String(x||'').toLowerCase()).find(x=>SKILL_ICONS.has(x));return '/client-assets/skill-'+(s||'overall')+'.png';};
