 // Game results, newest first: the live ones or the practice ones. Equal results in a row fold into one line with a count.
 const KV=/(^|\s)([A-Za-z][A-Za-z0-9]*)=(\S+)/g;
 function readable(text){const t=String(text??''),pairs=[...t.matchAll(KV)];if(pairs.length<2)return E(t);const head=t.slice(0,pairs[0].index).trim(),last=pairs[pairs.length-1],tail=t.slice(last.index+last[0].length).trim();return (head?'<b>'+E(head)+'</b> ':'')+pairs.map(p=>E(p[2].replace(/([a-z0-9])([A-Z])/g,'$1 $2').toLowerCase())+' '+E(/^\d{4,}$/.test(p[3])?Number(p[3]).toLocaleString():p[3])).join(' · ')+(tail?' '+E(tail):'');}
 const word=k=>k.replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/_/g,' ').toLowerCase(),shown=v=>typeof v==='number'&&Math.abs(v)>=1000?v.toLocaleString():String(v);
 function resultSummary(text,limit=8){
  const t=String(text??'').replace(/^(ok|fail)\b\s*/,''),brace=t.indexOf('{');
  // Status files cut long results, so the JSON is often unfinished: read its "key":value pairs one by one.
  if(brace>=0){const head=t.slice(0,brace).trim(),o={};for(const m of t.slice(brace).matchAll(/"([A-Za-z_][\w]*)":("(?:[^"\\]|\\.)*"|-?\d+(?:\.\d+)?|true|false|null)/g)){try{o[m[1]]=JSON.parse(m[2]);}catch{/* skip */}}if(Object.keys(o).length){const first=['error','reason','failure','stop','phase','targetMet'].filter(k=>o[k]!=null&&typeof o[k]!=='object');const rest=Object.keys(o).filter(k=>!first.includes(k)&&k!=='ok'&&o[k]!=null&&typeof o[k]!=='object'&&o[k]!==''&&o[k]!==0&&o[k]!==false);
   return (head?'<b>'+E(head)+'</b> ':'')+[...first,...rest].slice(0,limit).map(k=>E(word(k))+' '+E(shown(o[k]))).join(' · ');}}
  return readable(t);
 }
